10	import { handleSyncProductboardNotes } from "./handlers/sync-productboard-notes";
11	import { handleSyncProductboardFeatures } from "./handlers/sync-productboard-features";
12	import { handleSyncFrontCustomerConversations } from "./handlers/sync-front-customer-conversations";
13	import { handleSyncProductboardCustomerNotes } from "./handlers/sync-productboard-customer-notes";
14	import { handleImportConsumption } from "./handlers/import-consumption";
15	import { handleDetectUsageDrops } from "./handlers/detect-usage-drops";
16	import { cleanupStaleJobs } from "@/lib/jobs/cleanup";
17	
18	async function startWorker() {
19	  try {
20	    logger.log("Starting pg-boss worker...");
21	    const boss = await getBoss();
22	
23	    // Clean up any stale jobs from previous runs
24	    logger.log("Cleaning up stale jobs...");
25	    await cleanupStaleJobs();
26	
27	    // Create queues before registering workers
28	    const queues = [
29	      "sync-front-accounts",
30	      "sync-front-contacts",
31	      "sync-front-account-contacts",
32	      "sync-front-conversations",
33	      "sync-front-account-conversations",
34	      "sync-front-customer-conversations",
35	      "sync-productboard-companies",
36	      "sync-productboard-notes",
37	      "sync-productboard-customer-notes",
38	      "sync-productboard-features",
39	      "import-consumption",
40	      "detect-usage-drops",
41	    ];
42	
43	    logger.log("Creating job queues...");
44	    for (const queue of queues) {
45	      await boss.createQueue(queue);
46	    }
47	
48	    // Register job handlers
49	    await boss.work("sync-front-accounts", handleSyncFrontAccounts);
50	    await boss.work("sync-front-contacts", handleSyncFrontContacts);
51	    await boss.work("sync-front-conversations", handleSyncFrontConversations);
52	
53	    // Register sub-job handlers with concurrency options
54	    const frontConcurrency = 3 * Math.max(1, getApiTokenCount());
55	    logger.log(`[Worker] Front sub-job concurrency: ${frontConcurrency} (${Math.max(1, getApiTokenCount())} API key(s))`);
56	
57	    await boss.work(
58	      "sync-front-account-contacts",
59	      {
60	        localConcurrency: frontConcurrency,
61	      },
62	      handleSyncFrontAccountContacts
63	    );
64	
65	    await boss.work(
66	      "sync-front-account-conversations",
67	      {
68	        localConcurrency: frontConcurrency,
69	      },
70	      handleSyncFrontAccountConversations
71	    );
72	
73	    await boss.work("sync-productboard-companies", handleSyncProductboardCompanies);
74	    await boss.work("sync-productboard-notes", handleSyncProductboardNotes);
75	    await boss.work("sync-productboard-features", handleSyncProductboardFeatures);
76	    await boss.work("sync-front-customer-conversations", handleSyncFrontCustomerConversations);
77	    await boss.work("sync-productboard-customer-notes", handleSyncProductboardCustomerNotes);
78	    await boss.work("import-consumption", handleImportConsumption);
79	    await boss.work("detect-usage-drops", handleDetectUsageDrops);
80	
81	    logger.log("✓ Worker started successfully, listening for jobs...");
82	
83	    // Handle graceful shutdown
84	    process.on("SIGINT", async () => {
85	      logger.log("\nShutting down worker...");
86	      await closeBoss();
87	      process.exit(0);
88	    });
89	
90	    process.on("SIGTERM", async () => {
91	      logger.log("\nShutting down worker...");
92	      await closeBoss();
93	      process.exit(0);
94	    });
95	  } catch (error) {
96	    console.error("Failed to start worker:", error);
97	    process.exit(1);
98	  }
99	}
100	
101	startWorker();
