import {
  clerkMiddleware,
  createRouteMatcher,
} from "@clerk/nextjs/server";
import { NextResponse } from "next/server";

// Routes that don't require authentication
const isPublicRoute = createRouteMatcher([
  "/sign-in(.*)",
  "/sign-up(.*)",
  "/api/health/(.*)",
]);

export default clerkMiddleware(async (auth, request) => {
  // Allow public routes without any auth
  if (isPublicRoute(request)) {
    return NextResponse.next();
  }

  // For all other routes, require Clerk authentication
  const { userId } = await auth();
  if (!userId) {
    // For API routes, return 401 JSON response instead of redirecting
    if (request.nextUrl.pathname.startsWith("/api/")) {
      return NextResponse.json(
        { error: "Unauthorized" },
        { status: 401 }
      );
    }

    // For server actions, pass through to the handler (which has its own auth checks)
    // This ensures the response is in RSC format that Next.js expects
    // Server actions are POST requests with the Next-Action header and specific content-type
    // (either multipart/form-data for forms with files, or text/plain for regular actions)
    const contentType = request.headers.get("content-type");
    const isServerAction =
      request.method === "POST" &&
      request.headers.get("Next-Action") &&
      (contentType?.includes("multipart/form-data") || contentType?.includes("text/plain"));
    if (isServerAction) {
      return NextResponse.next();
    }

    // For page routes, redirect to sign-in
    const signInUrl = new URL("/sign-in", request.url);
    signInUrl.searchParams.set("redirect_url", request.url);
    return NextResponse.redirect(signInUrl);
  }

  return NextResponse.next();
});

export const config = {
  matcher: [
    // Skip Next.js internals and static files
    "/((?!_next|[^?]*\\.(?:html?|css|js(?!on)|jpe?g|webp|png|gif|svg|ttf|woff2?|ico|csv|docx?|xlsx?|zip|webmanifest)).*)",
    // Always run for API routes
    "/(api|trpc)(.*)",
  ],
};

